//! Explicit lifecycle operations kept separate from creation/review handlers.
use axum::{extract::{State,Path},Json};
use serde::Deserialize;
use serde_json::{json,Value};
use sea_orm::TransactionTrait;
use uuid::Uuid;
use chrono::{DateTime,Utc};
use crate::{AppState,auth::Principal,error::{ApiError,Result},validation};
use super::audit;

#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct PendingPerson {pub display_name:String,pub email:Option<String>,pub position_posting_id:Option<Uuid>,pub unverified_myfwa_id:Option<String>,pub answers_json:Option<Value>}
pub async fn pending_person(State(s):State<AppState>,p:Principal,Json(b):Json<PendingPerson>)->Result<Json<Value>>{
 p.require(&s,"people.edit",None).await?;validation::text(&b.display_name,120)?;
 if b.email.as_ref().is_some_and(|e|e.len()>254||!e.contains('@')){return Err(ApiError::bad("Invalid contact email"));}if let Some(id)=&b.unverified_myfwa_id{validation::text(id,120)?;}
 let mut tx=s.db.begin().await?;
 let id:Uuid=crate::repositories::lifecycle::pending_person_insert_users(&tx, (&b.display_name).to_owned(), (b.email).to_owned()).await?;
 let mut application_id:Option<Uuid>=None;
 if let Some(post)=b.position_posting_id{let row=crate::repositories::lifecycle::pending_person_select_position_postings(&tx, (post).to_owned()).await?;p.require(&s,"applications.review",Some(row.try_get("", "department_id")?)).await?;let answers=b.answers_json.unwrap_or(json!({}));validation::validate_answers(&row.try_get("", "schema_json")?,&answers)?;
 application_id=Some(crate::repositories::lifecycle::pending_person_insert_applications(&tx, (post).to_owned(), (id).to_owned(), (b.unverified_myfwa_id).to_owned(), (answers).to_owned()).await?);
 }else if b.unverified_myfwa_id.is_some(){return Err(ApiError::bad("Unverified provider IDs may only be kept as application intake evidence"));}
 audit(&mut tx,p.id,"person.pending_provisioned","user",id,Value::Null,json!({"status":"pending_identity","application_id":application_id})).await?;tx.commit().await?;Ok(Json(json!({"id":id,"application_id":application_id,"status":"pending_identity"})))
}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct DepartmentPatch {pub name:Option<String>,pub description:Option<String>,pub lead_user_id:Option<Uuid>,pub clear_lead:Option<bool>,pub active:Option<bool>}
pub async fn department(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<DepartmentPatch>)->Result<Json<Value>>{p.require(&s,"organization.manage",Some(id)).await?;if let Some(name)=&b.name{validation::text(name,100)?;}if b.description.as_ref().is_some_and(|v|v.len()>4000){return Err(ApiError::bad("Description is too long"));}let mut tx=s.db.begin().await?;if let Some(lead)=b.lead_user_id{let member:bool=crate::repositories::lifecycle::department_select_user_departments(&tx,(id).to_owned(),lead).await?;if !member{return Err(ApiError::bad("Department lead must be an active department member"));}}crate::repositories::lifecycle::department_update_departments(&tx, (id).to_owned(), (b.name).to_owned(), (b.description).to_owned(), (b.lead_user_id).to_owned(), (b.clear_lead.unwrap_or(false)).to_owned(), (b.active).to_owned()).await?;audit(&mut tx,p.id,"department.updated","department",id,Value::Null,json!({"updated":true})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
pub async fn division(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<DepartmentPatch>)->Result<Json<Value>>{p.require(&s,"organization.manage",None).await?;if let Some(name)=&b.name{validation::text(name,100)?;}let mut tx=s.db.begin().await?;crate::repositories::lifecycle::division_update_divisions(&tx, (id).to_owned(), (b.name).to_owned(), (b.description).to_owned(), (b.lead_user_id).to_owned(), (b.clear_lead.unwrap_or(false)).to_owned(), (b.active).to_owned()).await?;audit(&mut tx,p.id,"division.updated","division",id,Value::Null,json!({"updated":true})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct SavedPatch {pub name:String,pub filter_ast_json:Value,pub shared_scope:String}
pub async fn update_list(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<SavedPatch>)->Result<Json<Value>>{validation::text(&b.name,120)?;super::lists::validate_filter(&b.filter_ast_json,0)?;if !["private","hr"].contains(&b.shared_scope.as_str()){return Err(ApiError::bad("Choose private or HR sharing"));}if b.shared_scope=="hr"{p.require(&s,"people.read",None).await?;}let mut tx=s.db.begin().await?;let n=crate::repositories::lifecycle::update_list_update_saved_lists(&tx, (id).to_owned(), (p.id).to_owned(), (b.name).to_owned(), (b.filter_ast_json).to_owned(), (&b.shared_scope).to_owned()).await?.rows_affected();if n==0{return Err(ApiError::missing());}audit(&mut tx,p.id,"list.updated","saved_list",id,Value::Null,json!({"shared_scope":b.shared_scope})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct InterviewPatch{pub scheduled_start_at:DateTime<Utc>,pub scheduled_end_at:DateTime<Utc>,pub timezone:String,pub location_label:String,pub location_url:Option<String>,pub status:String}
pub async fn interview(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<InterviewPatch>)->Result<Json<Value>>{
 let dept:Uuid=crate::repositories::lifecycle::interview_select_interviews(&s.db, (id).to_owned()).await?;p.require(&s,"interviews.manage",Some(dept)).await?;validation::text(&b.location_label,200)?;
 if !["scheduled","completed","cancelled"].contains(&b.status.as_str())||b.scheduled_end_at<=b.scheduled_start_at||(b.scheduled_end_at-b.scheduled_start_at).num_hours()>8||b.location_url.as_ref().is_some_and(|s|!s.starts_with("https://")||s.len()>2000){return Err(ApiError::bad("Invalid interview details"));}let timezone:bool=crate::repositories::lifecycle::interview_select_pg_timezone_names(&s.db, (&b.timezone).to_owned()).await?;if !timezone{return Err(ApiError::bad("Invalid timezone"));}
 let mut tx=s.db.begin().await?;crate::repositories::lifecycle::interview_update_interviews(&tx, (id).to_owned(), (b.scheduled_start_at).to_owned(), (b.scheduled_end_at).to_owned(), (b.timezone).to_owned(), (b.location_label).to_owned(), (b.location_url).to_owned(), (&b.status).to_owned()).await?;audit(&mut tx,p.id,"interview.updated","interview",id,Value::Null,json!({"status":b.status})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))
}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct PanelMember{pub interviewer_user_id:Uuid}
pub async fn add_interviewer(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<PanelMember>)->Result<Json<Value>>{let dept:Uuid=crate::repositories::lifecycle::add_interviewer_select_interviews(&s.db, (id).to_owned()).await?;p.require(&s,"interviews.manage",Some(dept)).await?;if !(Principal{id:b.interviewer_user_id}).can(&s,"interviews.decide",Some(dept)).await?{return Err(ApiError::bad("Interviewer needs explicit decision permission"));}let mut tx=s.db.begin().await?;crate::repositories::lifecycle::add_interviewer_insert_interview_participants(&tx, (id).to_owned(), (b.interviewer_user_id).to_owned(), (p.id).to_owned()).await?;audit(&mut tx,p.id,"interview.panel_assigned","interview",id,Value::Null,json!({"interviewer_user_id":b.interviewer_user_id})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct Owner {pub hiring_owner_user_id:Uuid,pub reason:String}
pub async fn owner(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<Owner>)->Result<Json<Value>>{validation::text(&b.reason,1000)?;let mut tx=s.db.begin().await?;let row=crate::repositories::lifecycle::owner_select_position_postings(&tx, (id).to_owned()).await?;let dept:Uuid=row.try_get("", "department_id")?;p.require(&s,"positions.manage",Some(dept)).await?;if !(Principal{id:b.hiring_owner_user_id}).can(&s,"interviews.finalize",Some(dept)).await?{return Err(ApiError::bad("New owner needs explicit finalization permission"));}crate::repositories::lifecycle::owner_update_position_postings(&tx, (id).to_owned(), (b.hiring_owner_user_id).to_owned()).await?;audit(&mut tx,p.id,"position.owner_reassigned","position",id,json!({"hiring_owner_user_id":row.try_get::<Uuid>("", "hiring_owner_user_id")?}),json!({"hiring_owner_user_id":b.hiring_owner_user_id,"reason":b.reason})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct Reopen {pub reason:String}
pub async fn reopen(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<Reopen>)->Result<Json<Value>>{validation::text(&b.reason,2000)?;let mut tx=s.db.begin().await?;let row=crate::repositories::lifecycle::reopen_select_volunteer_entries(&tx, (id).to_owned()).await?;p.require(&s,"volunteer.time.admin",Some(row.try_get("", "department_id")?)).await?;if !["approved","rejected"].contains(&row.try_get::<String>("", "status")?.as_str()){return Err(ApiError::conflict("Only decided entries can be reopened"));}
 crate::repositories::lifecycle::reopen_insert_volunteer_adjustments(&tx, (id).to_owned(), (p.id).to_owned(), (b.reason).to_owned(), (row.try_get::<Value>("", "snapshot")?).to_owned()).await?;
 crate::repositories::lifecycle::reopen_update_volunteer_entries(&tx, (id).to_owned()).await?;crate::repositories::lifecycle::reopen_update_volunteer_approval_tokens(&tx, (id).to_owned()).await?;audit(&mut tx,p.id,"volunteer.reopened","volunteer_entry",id,json!({"status":row.try_get::<String>("", "status")?}),json!({"status":"draft","history_preserved":true})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
pub async fn edit_entry(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>,Json(b):Json<super::volunteers::Entry>)->Result<Json<Value>>{let minutes=super::volunteers::duration(&b)?;if minutes>s.config.max_volunteer_minutes{return Err(ApiError::bad("Duration exceeds the configured maximum"));}validation::text(&b.work_description,2000)?;if b.work_date>Utc::now().date_naive()||b.ended_at.is_some_and(|end|end>Utc::now()){return Err(ApiError::bad("Work date and end time cannot be in the future"));}p.require(&s,"volunteer.time.submit",Some(b.department_id)).await?;let mut tx=s.db.begin().await?;
 crate::repositories::lifecycle::edit_entry_select_users(&tx, (p.id).to_owned()).await?;let row=crate::repositories::lifecycle::edit_entry_select_volunteer_entries(&tx, (id).to_owned()).await?;if row.try_get::<Uuid>("", "volunteer_user_id")?!=p.id||row.try_get::<String>("", "status")?!="draft"{return Err(ApiError::conflict("Only your own draft can be edited"));}let overlap:bool=crate::repositories::lifecycle::edit_entry_select_volunteer_entries_2(&tx, (p.id).to_owned(), (b.started_at).to_owned(), (b.ended_at).to_owned(), (id).to_owned()).await?;if overlap{return Err(ApiError::conflict("These times overlap another entry"));}
 crate::repositories::lifecycle::edit_entry_update_volunteer_entries(&tx, (id).to_owned(), (b.department_id).to_owned(), (b.event_edition_id).to_owned(), (b.work_date).to_owned(), (minutes).to_owned(), (b.started_at).to_owned(), (b.ended_at).to_owned(), (b.work_description).to_owned()).await?;audit(&mut tx,p.id,"volunteer.draft_edited","volunteer_entry",id,Value::Null,json!({"minutes":minutes})).await?;tx.commit().await?;Ok(Json(json!({"ok":true})))}
pub async fn job(State(s):State<AppState>,p:Principal,Path(id):Path<Uuid>)->Result<Json<Value>>{p.require(&s,"people.bulk_update",None).await?;let data:Value=crate::repositories::lifecycle::job_select_bulk_change_jobs(&s.db, (id).to_owned(), (p.id).to_owned()).await?;Ok(Json(data))}
